    24		public void AddGlow(Vector2 loc, float r, float g, float b, float size, int type)
    25		{
    26			_ = (int)loc.X;
    27			_ = 7;
    28			float num = size * 64f;
    29			float num2 = 200f;
    30			if (!(loc.X + num < 0f) && !(loc.Y + num < 0f) && !(loc.X - num > ScrollManager.screenSize.X) && !(loc.Y - num > ScrollManager.screenSize.Y))
    31			{
    32				float num3 = 1f;
    33				if (loc.X < 0f - num2)
    34				{
    35					num3 *= 1f - (0f - loc.X - num2) / num;
    36				}
    37				if (loc.Y < 0f - num2)
    38				{
    39					num3 *= 1f - (0f - loc.Y - num2) / num;
    40				}
    41				if (loc.X > ScrollManager.screenSize.X + num2)
    42				{
    43					num3 *= 1f - (loc.X - (ScrollManager.screenSize.X + num2)) / num;
    44				}
    45				if (loc.Y > ScrollManager.screenSize.Y + num2)
    46				{
    47					num3 *= 1f - (loc.Y - (ScrollManager.screenSize.Y + num2)) / num;
    48				}
    49				if (totalGlows < glow.Length)
    50				{
    51					glow[totalGlows].Init(loc, r, g, b, size * num3, type);
    52					totalGlows++;
    53				}
    54			}
    55		}
    57		public void Draw(XTexture xt)
    58		{
    59			for (int i = 0; i < totalGlows; i++)
    60			{
    61				glow[i].Draw(xt, idx);
    62			}
    63		}
    65		internal void Clear()
    66		{
    67			totalGlows = 0;
    68		}
    70		internal void DrawForLightMode(XTexture xt)
    71		{
    72			for (int i = 0; i < totalGlows; i++)
    73			{
    74				glow[i].DrawForLightMode(xt, idx);
    75			}
    76		}
