    75		internal void Update()
    76		{
    77			if (greenLanternFrame > 0f)
    78			{
    79				greenLanternFrame -= Game1.frameTime;
    80				if (greenLanternAlpha < 1f)
    81				{
    82					greenLanternAlpha += Game1.frameTime;
    83					if (greenLanternAlpha > 1f)
    84					{
    85						greenLanternAlpha = 1f;
