    98			addVec[0].Y += Game1.frameTime * 4f;
    99			addVec[1].X += Game1.frameTime * -3.5f;
   100			addVec[1].Y += Game1.frameTime * -7f;
   101			addVec[2].X += Game1.frameTime * -6f;
   102			addVec[2].Y += Game1.frameTime * -2.5f;
   103			float num = 512f;
   104			for (int i = 0; i < addVec.Length; i++)
   105			{
   106				if (addVec[i].X >= num)
   107				{
   108					addVec[i].X -= num;
   109				}
   110				if (addVec[i].X < 0f)
   111				{
   112					addVec[i].X += num;
   113				}
   114				if (addVec[i].Y >= num)
   115				{
   116					addVec[i].Y -= num;
   117				}
   118				if (addVec[i].Y < 0f)
   119				{
   120					addVec[i].Y += num;
   121				}
   122			}
   123		}
