   130			Vector2 realLoc2 = ScrollManager.GetRealLoc(ScrollManager.screenSize, 2f);
   131			Vector2 realLoc3 = ScrollManager.GetRealLoc(new Vector2(0f, 0f), 6f);
   132			ScrollManager.GetRealLoc(ScrollManager.screenSize, 6f);
   133			Vector2 realLoc4 = ScrollManager.GetRealLoc(new Vector2(0f, 0f), 7f);
   134			ScrollManager.GetRealLoc(ScrollManager.screenSize, 7f);
   135			lightEffect.Parameters["scroll"].SetValue(realLoc + addVec[0]);
   136			lightEffect.Parameters["scroll2"].SetValue(realLoc3 + addVec[1]);
   137			lightEffect.Parameters["scroll3"].SetValue(realLoc4 + addVec[2]);
   138			lightEffect.Parameters["scrollDif"].SetValue(realLoc2 - realLoc);
   139			lightEffect.Parameters["lightFac"].SetValue(lightFac);
   140			SpriteTools.sprite.GraphicsDevice.Textures[1] = cloudsTex;
   141			lightEffect.Parameters["CloudsTexture"].SetValue(cloudsTex);
   142			lightEffect.Parameters["LightTexture"].SetValue(lightTarg);
   143			SpriteTools.BeginSubtractive(lightEffect);
   144			SpriteTools.sprite.Draw(lightTarg, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, alpha));
   145			SpriteTools.End();
   146			SpriteTools.sprite.GraphicsDevice.Textures[1] = null;
