    43				Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(glowVec[i] + new Vector2(num * -64f, 0f), 0), 0, new Vector2(0.75f, 0.75f) * ScrollManager.cannedDepth[0], 0f, 1f, 0.8f, 0.6f, 1f);
    44				MapMgr.glowMgr.Add(0, ScrollManager.GetScreenLoc(glowVec[i] + new Vector2(num * -64f * 0.5f, 0f), 0), 0.1f, 0.1f, 0.05f, 3f, 0);
