115			{
116				node[i].Draw(node[i - 1], r, g, b);
117			}
118			Textures.tex[ParticleManager.spritesTexIdx].Draw(ScrollManager.GetScreenLoc(node[0].loc, 0), node[0].idx, new Vector2(1f, 1f) * 0.2f * ScrollManager.cannedDepth[0], node[0].frame * 1f, r, g, b, 1f);
119		}
121		public void Update()
122		{
123			frame -= Game1.frameTime;
124			if (active)
125			{
126				addParticle = false;
127				float num = uberFrame;
128				uberFrame += Game1.frameTime;
129				if (uberFrame > 1f)
130				{
131					uberFrame--;
132				}
133				if ((int)(num * 60f) != (int)(uberFrame * 60f))
134				{
135					addParticle = true;
136				}
137			}
138			for (int i = 0; i < node.Length; i++)
139			{
140				node[i].Update();
141			}
142			for (int j = 1; j < node.Length - 1; j++)
143			{
144				if ((node[j - 1].loc + node[j + 1].loc).LengthSquared() > 500000f)
145				{
146					Vector2 vector = (node[j - 1].loc + node[j + 1].loc) / 2f;
147					node[j].loc += (vector - node[j].loc) * Game1.frameTime * 20f;
148				}
149			}
150			if (frame < -1f)
151			{
152				active = false;
153			}
154		}
156		public void Set(Vector2 loc)
157		{
158			active = true;
159			node[0].loc = loc;
160			if (addParticle && c.playerIdx > -1)
161			{
162				Player player = c.GetPlayer();
163				for (int i = 4; i < 8; i++)
164				{
165					if (player.runes[5] && Rand.CoinToss(0.1f))
166					{
167						Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
168						Rand.GetRandomFloat(0f, 100f);
169						ParticleManager.AddAdditiveParticle(141, node[i].loc, node[i].traj * 0.1f, Rand.GetRandomFloat(0.01f, 0.2f), 0f, 1, c.ID);
170					}
171					if (player.runes[4] && Rand.CoinToss(0.1f))
172					{
173						Rand.GetRandomFloat(0f, (float)Math.PI * 2f);
174						Rand.GetRandomFloat(0f, 100f);
175						ParticleManager.AddAdditiveParticle(141, node[i].loc, node[i].traj * 0.1f, Rand.GetRandomFloat(0.01f, 0.2f), 0f, 0, c.ID);
176					}
177				}
178			}
179			Sound.PlaySpre(3, loc, 0);
180			if (frame <= 0f)
181			{
182				frame = 0.05f;
183				for (int num = 15; num > 0; num--)
184				{
185					node[num].CopyFrom(node[num - 1]);
186				}
187				node[0].Init(loc);
188				if (c.buffs.GetUpsideDown())
189				{
190					node[0].traj.Y *= -1f;
191				}
192			}
193			if (!inited)
194			{
195				for (int j = 1; j < node.Length; j++)
196				{
197					node[j].loc = loc;
198					node[j].traj = Rand.GetRandomVec2(-1f, 1f, -1f, 1f) * 1000f;
199				}
200				inited = true;
201			}
202		}
